import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['RSPP-A','RSPP-AGG']
EA(K,'ZR20','La gestione del cambiamento',[LB("Laboratorio · Valutare un cambiamento organizzativo","La direzione di un’impresa di logistica vuole passare da due a tre turni e ridurre da 3 a 2 i carrellisti per turno.",[
  ["Situazione attuale","2 turni diurni, 3 carrellisti per turno, preposto presente in entrambi"],["Proposta","3 turni, incluso il notturno; 2 carrellisti per turno; preposto solo nei turni diurni"],["Dati","il 60% dei quasi incidenti avviene nelle ultime due ore di turno"]],[
  ("Quali nuovi rischi introduce il cambiamento?",7,"Lavoro notturno con affaticamento e calo di vigilanza; carichi di lavoro maggiori per carrellista; assenza del preposto nel turno notturno; lavoro con meno persone e soccorso più difficile; possibili ripercussioni sullo stress lavoro-correlato.",["Ho considerato il lavoro notturno","Ho considerato carichi e assenza del preposto","Ho considerato soccorso e stress"]),
  ("Chi coinvolgi e quando?",6,"Prima della decisione: RSPP e medico competente per la valutazione, RLS per la consultazione preventiva; i preposti per la fattibilità operativa; i lavoratori interessati per raccogliere le criticità.",["Ho coinvolto le figure prima della decisione","Ho previsto la consultazione dell’RLS"]),
  ("Quali condizioni poni perché il cambiamento sia accettabile?",8,"Preposto o figura con funzioni di vigilanza in ogni turno; sorveglianza sanitaria per i lavoratori notturni; pause e rotazioni; verifica dei carichi con i dati di movimentazione; procedura di emergenza e comunicazione per il notturno; illuminazione adeguata.",["Ho posto la vigilanza in ogni turno","Ho previsto sorveglianza e pause","Ho previsto le emergenze notturne"],None,120),
  ("Come verifichi gli effetti dopo l’avvio?",6,"Indicatori nei primi sei mesi: quasi incidenti e infortuni per turno, assenze, segnalazioni, rispetto delle pause; riesame dopo tre mesi con RSPP, medico competente e RLS e correzioni.",["Ho previsto indicatori per turno","Ho previsto un riesame programmato"])],
 "Nel laboratorio valuti un cambiamento organizzativo in un’impresa di logistica: nuovi rischi, figure da coinvolgere, condizioni di accettabilità e verifica degli effetti. Confronta ogni risposta con la soluzione di riferimento.","Artt. 28, 29 e 50 D.lgs. 81/2008 · UNI EN ISO 45001, punto 8.1.3")])
EA(K,'ZR21','Il processo di gestione del rischio (UNI ISO 31000)',[LB("Laboratorio · Il registro dei rischi secondo la ISO 31000","Imposti il registro dei rischi per il reparto saldatura di una carpenteria applicando il processo della UNI ISO 31000.",[
  ["Reparto","8 saldatori MIG e TIG, area di molatura adiacente"],["Pericoli noti","fumi di saldatura, radiazioni ottiche, incendio, rumore della molatura, ustioni"],["Criteri aziendali","matrice 4 × 4; rischi con R ≥ 9 da trattare entro tre mesi"]],[
  ("Definisci contesto e criteri prima di identificare i rischi.",6,"Obiettivi: proteggere salute e sicurezza dei saldatori e dei lavoratori vicini. Parti interessate: saldatori, molatori, RLS, medico competente. Criteri: scala di probabilità e danno con definizioni verificabili, soglia di trattamento R ≥ 9, criteri di accettabilità.",["Ho definito obiettivi e parti interessate","Ho reso espliciti i criteri"]),
  ("Compila tre righe del registro: pericolo, situazione, P, D, R, misure esistenti.",9,"Fumi di saldatura senza aspirazione su due banchi: P 3, D 4, R 12, misure esistenti solo ventilazione generale. Radiazioni ottiche verso i molatori: P 3, D 2, R 6, schermi parziali. Incendio da scintille su materiali combustibili: P 2, D 4, R 8, estintori. I valori vanno motivati.",["Ho compilato tre righe complete","Ho motivato P e D","Ho indicato le misure esistenti"],None,150),
  ("Proponi il trattamento per il rischio più alto.",6,"Fumi di saldatura, cancerogeni: aspirazione localizzata su tutti i banchi, torce aspiranti dove possibile, procedure che privilegiano processi a minore emissione, protezione respiratoria nelle fasi critiche, misure dell’esposizione e sorveglianza sanitaria.",["Ho privilegiato misure alla fonte","Ho previsto misure e sorveglianza"]),
  ("Come monitori e riesamini il registro?",6,"Rivalutazione dopo l’attuazione per stimare il rischio residuo; riesame almeno annuale e a ogni cambiamento; registrazione delle decisioni e comunicazione al reparto.",["Ho previsto il rischio residuo","Ho previsto il riesame periodico"])],
 "Nel laboratorio applichi il processo della UNI ISO 31000 al reparto saldatura: contesto e criteri, righe del registro, trattamento e riesame. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 31000 · art. 28 D.lgs. 81/2008")])
EA(K,'ZR22','Esempio applicativo: un metodo a indici per il rischio chimico per la sicurezza',[LB("Laboratorio · Applicare il metodo a indici","Applichi il metodo a indici al travaso di un solvente infiammabile in magazzino.",[
  ["Lista di controllo","messa a terra assente durante il travaso; contenitori non omologati; ventilazione insufficiente"],["Scala di deficienza LD","10 molto carente · 6 carente · 2 migliorabile · 0 accettabile"],["Scala di esposizione LE","4 continua · 3 frequente · 2 occasionale · 1 sporadica"],["Travasi","più volte al giorno"],["Conseguenze LC","25 per lesioni gravi con inabilità temporanea; 60 per lesioni molto gravi"],["Livelli di rischio","I da 600 a 4.000; II da 150 a 500; III da 40 a 120; IV fino a 20"]],[
  ("Assegna LD, LE e calcola LP.",6,"LD = 6, carente: diverse carenze significative. LE = 3, esposizione frequente. LP = LD × LE = 18.",["Ho scelto LD motivandolo","Ho scelto LE","Ho calcolato LP = 18"]),
  ("Scegli LC e calcola il livello di rischio.",6,"Un incendio durante il travaso può causare lesioni gravi: LC = 25. LR = LP × LC = 18 × 25 = 450: livello II.",["Ho scelto LC","Ho calcolato 450","Ho individuato il livello II"]),
  ("Che cosa significa il livello II e quali misure servono?",7,"Il rischio va corretto con misure di controllo in tempi brevi: messa a terra ed equipotenzialità durante il travaso, contenitori omologati, ventilazione e quantità limitate; formazione. Dopo le misure si ricalcola LR.",["Ho interpretato il livello II","Ho proposto misure mirate alle carenze","Ho previsto il ricalcolo"])],
 "Nel laboratorio applichi un metodo a indici al travaso di un solvente infiammabile: livelli di deficienza, esposizione e conseguenze, livello di rischio e misure. Confronta ogni risposta con la soluzione di riferimento.","Metodo a indici di probabilità e conseguenze · art. 28 D.lgs. 81/2008")])
EA(K,'ZR23','Indicatori infortunistici: frequenza e gravità (UNI 7249)',[LB("Laboratorio · Il cruscotto degli indicatori","Prepari il cruscotto degli indicatori di sicurezza di uno stabilimento per tre anni.",[
  ["2023","7 infortuni, 160 giornate perse, 410.000 ore, 5 quasi incidenti segnalati"],["2024","5 infortuni, 210 giornate perse, 400.000 ore, 22 quasi incidenti segnalati"],["2025","4 infortuni, 60 giornate perse, 420.000 ore, 41 quasi incidenti segnalati"]],[
  ("Calcola indice di frequenza e indice di gravità per i tre anni.",8,"IF 2023 = 7 × 1.000.000 / 410.000 ≈ 17,1; 2024 ≈ 12,5; 2025 ≈ 9,5. IG 2023 = 160 × 1.000 / 410.000 ≈ 0,39; 2024 ≈ 0,53; 2025 ≈ 0,14.",["Ho calcolato i tre IF","Ho calcolato i tre IG"]),
  ("Interpreta l’andamento.",6,"La frequenza cala in modo costante; la gravità nel 2024 cresce per uno o due eventi lunghi, poi scende. Con numeri piccoli le variazioni annuali vanno lette con cautela. L’aumento dei quasi incidenti segnalati indica una cultura della segnalazione che migliora, non un peggioramento.",["Ho distinto frequenza e gravità","Ho considerato i piccoli numeri","Ho interpretato i quasi incidenti"]),
  ("Quali indicatori proattivi aggiungi al cruscotto?",6,"Sopralluoghi della direzione svolti; azioni correttive chiuse nei tempi; ore di formazione per lavoratore; percentuale di quasi incidenti analizzati; osservazioni di comportamento.",["Ho proposto almeno quattro indicatori proattivi","Ho collegato gli indicatori alle azioni"])],
 "Nel laboratorio prepari il cruscotto degli indicatori di uno stabilimento: calcoli frequenza e gravità per tre anni, interpreti l’andamento e aggiungi indicatori proattivi. Confronta ogni risposta con la soluzione di riferimento.","UNI 7249:2007 · UNI EN ISO 45001, punto 9.1")])
EA(K,'ZR24','Esempio applicativo: dalla non conformità alla priorità dell’azione',[LB("Laboratorio · Dall’audit al piano d’azione","Trasformi gli esiti di un audit di sicurezza in un piano d’azione con priorità.",[
  ["Rilievo 1","verifica periodica dell’impianto di terra scaduta da 8 mesi"],["Rilievo 2","due estintori senza cartellino di controllo"],["Rilievo 3","procedura di blocco delle macchine non aggiornata dopo l’arrivo di una nuova linea"],["Rilievo 4","bacheca della sicurezza con organigramma non aggiornato"]],[
  ("Classifica ogni rilievo per esito e importanza del requisito.",7,"1: non conformità, requisito di legge con sanzione: importanza alta. 2: non conformità sui controlli antincendio, importanza alta. 3: non conformità di sistema con potenziale gravità elevata: importanza alta. 4: deviazione minore, importanza bassa.",["Ho classificato gli esiti","Ho graduato l’importanza dei requisiti"]),
  ("Stabilisci priorità, responsabile e scadenza.",7,"Priorità 1: procedura di blocco della nuova linea, ufficio tecnico, entro due settimane, per la gravità potenziale. Priorità 1: verifica dell’impianto di terra con organismo abilitato, datore di lavoro, entro un mese. Priorità 2: controllo degli estintori, manutentore, entro una settimana perché rapido. Priorità 3: aggiornamento della bacheca, RSPP, entro un mese.",["Ho motivato le priorità","Ho indicato responsabili e scadenze"]),
  ("Come chiudi e verifichi le azioni?",6,"Evidenze di chiusura, come il verbale di verifica, i cartellini e la procedura firmata; verifica di efficacia al successivo audit; registro delle azioni con stato aggiornato.",["Ho previsto le evidenze","Ho previsto la verifica di efficacia"])],
 "Nel laboratorio trasformi quattro rilievi di audit in un piano d’azione: classificazione, priorità con responsabili e scadenze, chiusura e verifica. Confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 19011 · UNI EN ISO 45001, punto 10.2")])
EA(K,'ZR25','L’emendamento 2024 sul cambiamento climatico',[SC("Il clima nel sistema di gestione","Durante l’audit di una certificazione UNI EN ISO 45001 l’auditor chiede come l’organizzazione ha considerato il cambiamento climatico.",[
 ("Che cosa richiede l’emendamento del 2024?",[["Di determinare se il cambiamento climatico è un fattore rilevante nel contesto e se le parti interessate hanno requisiti in merito",True,"Corretto: punti 4.1 e 4.2."],["Di calcolare l’impronta di carbonio",False,"Non è richiesto dalla norma."],["Nulla di nuovo",False,"L’emendamento introduce questa valutazione."]]),
 ("Per un’impresa edile, quale aspetto di sicurezza è più rilevante?",[["L’esposizione dei lavoratori a ondate di calore e a eventi meteorologici estremi",True,"Corretto: riguarda direttamente salute e sicurezza."],["Il prezzo dell’energia",False,"È un aspetto economico."],["Nessuno",False,"Il calore è un rischio rilevante."]]),
 ("Come lo documenti?",[["Nell’analisi del contesto e nei rischi e opportunità, con le misure collegate, come i piani per il caldo",True,"Corretto."],["Con una dichiarazione generica",False,"Serve un’analisi."],["Non serve documentarlo",False,"L’auditor chiede evidenze."]])],
 "Il cambiamento climatico entra nell’analisi del contesto: per la sicurezza significa soprattutto calore ed eventi estremi, da trasformare in rischi, misure ed evidenze.","Un auditor chiede del cambiamento climatico. Rispondi con evidenze.","UNI EN ISO 45001:2023 + A1:2024")])
EA(K,'ZR26','Il burnout nella classificazione dell’OMS',[SC("I segnali in reparto","In un reparto di assistenza domiciliare il coordinatore nota assenze ripetute, cinismo verso gli utenti e calo della qualità del lavoro in diverse operatrici.",[
 ("Come leggi questi segnali?",[["Possibili indicatori di burnout legati al contesto di lavoro: esaurimento, distacco e ridotta efficacia",True,"Corretto: sono le tre dimensioni descritte dall’OMS."],["Mancanza di impegno individuale",False,"Il burnout è legato al contesto lavorativo."],["Malattia da diagnosticare in azienda",False,"Non è una diagnosi aziendale."]]),
 ("Che cosa fai come RSPP?",[["Proponi di aggiornare la valutazione dello stress lavoro-correlato per il gruppo e di coinvolgere il medico competente",True,"Corretto."],["Chiedi provvedimenti disciplinari",False,"Non agisce sulle cause."],["Aspetti la prossima valutazione triennale",False,"I segnali richiedono di intervenire."]]),
 ("Quali misure organizzative sono pertinenti?",[["Carichi e turni sostenibili, supervisione e confronto sui casi difficili, autonomia nella pianificazione",True,"Corretto."],["Più controlli sulle presenze",False,"Non riducono il carico."],["Corsi motivazionali e basta",False,"Non agiscono sull’organizzazione."]])],
 "Il burnout è un fenomeno legato al contesto di lavoro: si riconosce dai segnali di gruppo e si affronta con la valutazione dello stress e misure organizzative.","Segnali di disagio in un reparto di assistenza. Interpreta e intervieni.","ICD-11, QD85 · art. 28 D.lgs. 81/2008")])
EA(K,'ZR27','Radon nei luoghi di lavoro: obblighi del D.lgs. 101/2020',[ES("Esempio guidato · La concentrazione media annua di radon","Un ufficio al piano seminterrato.",[
 ["Le misure","Due dispositivi esposti per due semestri consecutivi: 250 Bq/m³ in estate e 450 Bq/m³ in inverno.","250 · 450 Bq/m³"],
 ["La media annua","Media dei due semestri: (250 + 450) / 2 = 350 Bq/m³.","350 Bq/m³"],
 ["Il riferimento","Livello di riferimento per i luoghi di lavoro: 300 Bq/m³ di concentrazione media annua.","350 > 300"],
 ["Le azioni","Misure correttive, ad esempio ventilazione o depressurizzazione del vespaio, da progettare con un esperto in interventi di risanamento.","Risanamento"],
 ["La verifica","Nuova misura annuale dopo gli interventi per verificarne l’efficacia; se non si scende sotto il livello, valutazione delle dosi dei lavoratori.","Verifica"]],
 "Calcoliamo la concentrazione media annua di radon in un ufficio seminterrato. Le due misure semestrali valgono duecentocinquanta e quattrocentocinquanta becquerel per metro cubo: la media è trecentocinquanta, oltre il livello di riferimento di trecento. Servono misure correttive progettate da un esperto e una nuova misura annuale per verificarne l’efficacia.","D.lgs. 101/2020, artt. 12, 16 e 17")])
EA(K,'ZR28','Il rumore: valori di azione e obblighi',[LB("Laboratorio · Calcolare il livello di esposizione giornaliera","Calcoli l’esposizione giornaliera al rumore di un addetto alla carpenteria.",[
  ["Attività 1","molatura: 92 dB(A) per 2 ore"],["Attività 2","assemblaggio: 85 dB(A) per 4 ore"],["Attività 3","ufficio tecnico: 70 dB(A) per 2 ore"],["Formula","LEX,8h = 10 log[(1/8) Σ Ti · 10^(LAeq,i/10)]"]],[
  ("Calcola LEX,8h.",8,"Contributi: 2 × 10^9,2 ≈ 3,17 × 10⁹; 4 × 10^8,5 ≈ 1,26 × 10⁹; 2 × 10^7 = 0,02 × 10⁹. Somma ≈ 4,45 × 10⁹; diviso 8 ≈ 5,57 × 10⁸. LEX,8h = 10 log(5,57 × 10⁸) ≈ 87,5 dB(A).",["Ho calcolato i contributi","Ho applicato la formula","Ho ottenuto circa 87,5 dB(A)"],None,60),
  ("Confronta con i valori di riferimento e indica gli obblighi.",6,"Oltre il valore superiore di azione di 85 dB(A): programma di misure tecniche e organizzative, segnaletica e delimitazione delle aree, uso obbligatorio degli otoprotettori, sorveglianza sanitaria. Il valore limite di 87 dB(A) va verificato tenendo conto dell’attenuazione dei DPI.",["Ho confrontato con 85 e 87 dB(A)","Ho elencato gli obblighi"]),
  ("Quale intervento riduce di più e di quanto?",7,"La molatura contribuisce per circa il 70%. Riducendola a 1 ora: somma ≈ 2,87 × 10⁹, LEX ≈ 85,5 dB(A). Con una mola a minore emissione a 88 dB(A) per 2 ore: somma ≈ 2,55 × 10⁹, LEX ≈ 85,0 dB(A).",["Ho individuato il contributo dominante","Ho ricalcolato LEX"],None,60)],
 "Nel laboratorio calcoli il livello di esposizione giornaliera al rumore di un addetto alla carpenteria, lo confronti con i valori di riferimento e valuti l’intervento più efficace. Confronta ogni risposta con la soluzione di riferimento.","Artt. 188-198 D.lgs. 81/2008 · UNI EN ISO 9612:2025")])
EA(K,'ZR29','Marcatura CE e requisiti delle attrezzature',[SC("La macchina usata","Un’impresa acquista da un’asta fallimentare una piegatrice del 1990, senza marcatura CE e senza istruzioni.",[
 ("Può essere usata così com’è?",[["No: va resa conforme ai requisiti dell’Allegato V prima della messa in servizio",True,"Corretto: le attrezzature costruite prima delle direttive devono rispettare l’Allegato V."],["Sì, se funziona",False,"Il funzionamento non è conformità."],["Sì, perché è anteriore alle direttive",False,"Deve comunque rispettare l’Allegato V."]]),
 ("Chi può venderla o noleggiarla?",[["Il venditore deve attestare la conformità ai requisiti dell’Allegato V, sotto la propria responsabilità",True,"Corretto: art. 72."],["Chiunque, senza obblighi",False,"La vendita di attrezzature non conformi è vietata."],["Solo il costruttore originale",False,"Non è necessario."]]),
 ("Che cosa fai prima di usarla?",[["Valutazione dei rischi, adeguamento con ripari e dispositivi, istruzioni d’uso, formazione e addestramento degli operatori",True,"Corretto."],["Solo la pulizia",False,"Non basta."],["La marcatura CE fatta dall’impresa",False,"Non è una procedura ammessa così."]])],
 "Le attrezzature usate senza marcatura CE si adeguano all’Allegato V prima dell’uso; chi le vende ne attesta la conformità e chi le usa le valuta, istruisce e addestra.","Una piegatrice usata senza marcatura CE. Decidi come procedere.","Artt. 70-72 e Allegato V D.lgs. 81/2008")])
EA(K,'ZR30','L’impianto di terra e le verifiche periodiche',[ES("Esempio guidato · Lo scadenzario delle verifiche dell’impianto di terra","Tre siti di un’impresa.",[
 ["Sito A","Stabilimento metalmeccanico ordinario, ultima verifica 2022.","Ogni 5 anni → 2027"],
 ["Sito B","Locale con pericolo di esplosione classificato, ultima verifica 2024.","Ogni 2 anni → 2026"],
 ["Sito C","Cantiere edile aperto nel 2026.","Ogni 2 anni"],
 ["Chi verifica","ASL o organismi abilitati, su richiesta del datore di lavoro.","Organismo abilitato"],
 ["Le evidenze","Dichiarazione di conformità iniziale e verbali delle verifiche conservati.","Documenti conservati"]],
 "Organizziamo lo scadenzario delle verifiche dell’impianto di terra. Lo stabilimento ordinario si verifica ogni cinque anni, quindi nel duemilaventisette. Il locale con pericolo di esplosione e il cantiere ogni due anni. Le verifiche le eseguono ASL o organismi abilitati su richiesta del datore di lavoro, e si conservano dichiarazione di conformità e verbali.","D.P.R. 462/2001")])
EA(K,'ZR31','Lavoro notturno e a turni',[SC("Il nuovo turno notturno","Un’impresa introduce un turno notturno dalle 22 alle 6 per un reparto di confezionamento.",[
 ("Chi è lavoratore notturno?",[["Chi svolge con regolarità almeno 3 ore nel periodo notturno, secondo la disciplina applicabile",True,"Corretto."],["Solo chi lavora tutta la notte ogni giorno",False,"Basta lo svolgimento regolare di almeno 3 ore."],["Nessuno se il turno è a rotazione",False,"Conta la regolarità."]]),
 ("Quale sorveglianza sanitaria è prevista?",[["Visita preventiva e periodica almeno ogni due anni",True,"Corretto."],["Nessuna",False,"È prevista."],["Solo su richiesta",False,"È obbligatoria."]]),
 ("Chi non può essere adibito al lavoro notturno?",[["Le lavoratrici dall’accertamento della gravidanza fino a un anno di età del bambino",True,"Corretto."],["I lavoratori sopra i 40 anni",False,"Non esiste questo divieto."],["I lavoratori con contratto a termine",False,"Non è un criterio."]])],
 "Il lavoro notturno richiede regole precise: definizione del lavoratore notturno, visite almeno biennali e divieti per le lavoratrici madri.","Un nuovo turno notturno. Applica le regole.","D.lgs. 66/2003 · D.lgs. 151/2001, art. 53")])
EA(K,'ZR32','Le categorie dei DPI e gli obblighi del lavoratore',[CL("Quale categoria di DPI?","Seleziona un dispositivo, poi la categoria secondo il Reg. (UE) 2016/425.",["Categoria I","Categoria II","Categoria III"],[
 ["Guanti da giardinaggio per lesioni superficiali",0,"Rischi minimi."],["Elmetto di protezione per l’industria",1,"Rischi diversi da quelli minimi e da quelli mortali."],
 ["Imbracatura anticaduta",2,"Protegge da rischi che possono causare morte o danni irreversibili."],["Semimaschera con filtri per vapori organici",2,"Protezione delle vie respiratorie: categoria III."],
 ["Occhiali da sole per uso professionale",0,"Rischi minimi."],["Otoprotettori",2,"Il rumore dannoso è tra i rischi della categoria III."]],
 "Sei dispositivi di protezione individuale. Assegna la categoria: da essa dipendono certificazione e obbligo di addestramento.","Reg. (UE) 2016/425, Allegato I · art. 77 D.lgs. 81/2008")])
EA(K,'ZR33','Esempio applicativo: scegliere guanti e otoprotettori',[LB("Laboratorio · Scegliere l’otoprotettore","Scegli l’otoprotettore per un addetto alla molatura.",[
  ["Esposizione","LC = 98 dB(C) durante la molatura"],["Candidati","inserti in schiuma SNR 37; cuffia SNR 28; inserti ad archetto SNR 22"],["Metodo SNR","L’A = LC − SNR"],["Criterio di protezione","L’A tra 70 e 75 dB(A): protezione buona; tra 75 e 80 o tra 65 e 70: accettabile; sotto 65: iperprotezione; sopra 80: insufficiente"]],[
  ("Calcola il livello effettivo all’orecchio per ciascun candidato.",6,"Inserti SNR 37: 98 − 37 = 61 dB(A). Cuffia SNR 28: 98 − 28 = 70 dB(A). Archetto SNR 22: 98 − 22 = 76 dB(A).",["Ho applicato il metodo SNR","Ho calcolato i tre valori"]),
  ("Quale scegli e perché?",6,"La cuffia, con 70 dB(A): protezione buona. Gli inserti in schiuma iperproteggono, isolando l’addetto e rendendo difficile la comunicazione; gli archetti sono accettabili ma al limite.",["Ho scelto la cuffia","Ho spiegato l’iperprotezione"]),
  ("Che cosa aggiungi perché la protezione sia reale?",6,"Addestramento all’uso, obbligatorio per i DPI di categoria III; compatibilità con occhiali e visiera; uso per tutto il tempo di esposizione, perché anche brevi periodi senza DPI riducono molto la protezione; pulizia e sostituzione dei cuscinetti.",["Ho previsto l’addestramento","Ho considerato compatibilità e tempo d’uso"])],
 "Nel laboratorio scegli l’otoprotettore per un addetto alla molatura con il metodo SNR: calcoli il livello all’orecchio, scegli il dispositivo e completi le condizioni d’uso. Confronta ogni risposta con la soluzione di riferimento.","UNI EN 458:2016 · art. 193 D.lgs. 81/2008")])
EA(K,'ZR34','Colori e forme della segnaletica di sicurezza',[CL("Che tipo di segnale?","Seleziona un segnale, poi la sua categoria.",["Divieto","Avvertimento","Prescrizione","Salvataggio o soccorso","Attrezzature antincendio"],[
 ["Cerchio rosso barrato con sigaretta",0,"Rosso, forma rotonda: divieto."],["Triangolo giallo con bordo nero e fiamma",1,"Avvertimento di pericolo."],
 ["Cerchio azzurro con guanti bianchi",2,"Azzurro, rotondo: prescrizione."],["Rettangolo verde con omino che corre verso una porta",3,"Verde: salvataggio."],
 ["Quadrato rosso con estintore",4,"Rosso, quadrato: attrezzature antincendio."],["Triangolo giallo con carrello elevatore",1,"Avvertimento."],
 ["Cerchio azzurro con cuffie",2,"Prescrizione."],["Quadrato verde con croce bianca",3,"Pronto soccorso."]],
 "Otto segnali di sicurezza descritti per forma, colore e simbolo. Indica la categoria di ciascuno.","Allegato XXV D.lgs. 81/2008 · UNI EN ISO 7010")])
EA(K,'ZR35','La gestione delle emergenze',[LB("Laboratorio · Il piano di emergenza di un capannone","Prepari lo schema del piano di emergenza di un capannone di 3.000 m² con 40 lavoratori su un turno.",[
  ["Attività","magazzino e piccola produzione con verniciatura"],["Persone","40 lavoratori, di cui uno in sedia a ruote; visitatori occasionali"],["Rischi","incendio, sversamento di solventi, infortunio grave"],["Presidi","estintori, idranti, due uscite di emergenza, impianto di allarme"]],[
  ("Elenca i ruoli e chi li ricopre.",6,"Coordinatore dell’emergenza e sostituto; addetti antincendio e primo soccorso in numero adeguato; addetto alla chiamata dei soccorsi; addetto all’assistenza del lavoratore in sedia a ruote; addetti all’intercettazione delle utenze; responsabile del punto di raccolta.",["Ho previsto coordinamento e sostituto","Ho previsto l’assistenza alla persona con disabilità"]),
  ("Descrivi la sequenza per un principio di incendio in verniciatura.",8,"Chi scopre l’incendio dà l’allarme; gli addetti valutano l’intervento con estintori adeguati senza esporsi; se non è controllabile, il coordinatore ordina l’evacuazione; chiamata al 112 con informazioni precise; intercettazione di gas ed energia; evacuazione verso il punto di raccolta; appello; accoglienza dei soccorsi con informazioni sui solventi.",["Ho descritto allarme e primo intervento","Ho descritto evacuazione e appello","Ho previsto le informazioni ai soccorsi"],None,120),
  ("Quali allegati e verifiche prevedi?",6,"Planimetrie con vie di esodo, presidi e punto di raccolta; numeri utili; schede di sicurezza dei solventi; registro dei controlli antincendio; esercitazione almeno annuale con verbale e azioni di miglioramento.",["Ho previsto le planimetrie","Ho previsto le esercitazioni annuali"]),
  ("Come includi visitatori e imprese esterne?",5,"Informazione all’ingresso, registro delle presenze, accompagnamento nelle aree a rischio, procedure di emergenza nel DUVRI e coordinamento con le imprese presenti.",["Ho previsto informazione e registro","Ho collegato il DUVRI"])],
 "Nel laboratorio prepari lo schema del piano di emergenza di un capannone: ruoli, sequenza per un incendio, allegati e verifiche, gestione di visitatori e imprese esterne. Confronta ogni risposta con la soluzione di riferimento.","Artt. 43-46 D.lgs. 81/2008 · D.M. 2 settembre 2021")])
EA(K,'ZR36','La sorveglianza sanitaria',[ES("Esempio guidato · Il calendario della sorveglianza sanitaria","Le visite di un nuovo carrellista esposto a rumore.",[
 ["Prima dell’adibizione","Visita preventiva, anche in fase preassuntiva, con giudizio di idoneità.","Visita preventiva"],
 ["Durante il lavoro","Visita periodica secondo il protocollo: di norma annuale, o con la periodicità stabilita dal medico in base al rischio.","Visita periodica"],
 ["Su richiesta","Il lavoratore può chiedere una visita se correlata ai rischi professionali.","Visita su richiesta"],
 ["Dopo una lunga assenza","Visita alla ripresa dopo un’assenza per motivi di salute superiore a 60 giorni continuativi.","Ripresa > 60 giorni"],
 ["Cambio di mansione","Visita al cambio di mansione per verificare l’idoneità.","Cambio di mansione"]],
 "Vediamo il calendario della sorveglianza sanitaria di un carrellista esposto a rumore. Prima di iniziare fa la visita preventiva; poi le visite periodiche secondo il protocollo del medico competente. Può chiedere una visita se i disturbi sono legati al lavoro, e la fa alla ripresa dopo un’assenza per salute di oltre sessanta giorni e al cambio di mansione.","Art. 41 D.lgs. 81/2008")])
EA(K,'ZR37','Come apprendono gli adulti',[LB("Laboratorio · Progettare una lezione per adulti","Progetti una lezione di 60 minuti sull’uso sicuro delle scale portatili per addetti alla manutenzione.",[
  ["Partecipanti","12 manutentori esperti, poco propensi alla teoria"],["Evento recente","una caduta da scala senza conseguenze gravi"],["Spazi","aula e area con scale di diversi tipi"]],[
  ("Come apri la lezione per motivare i partecipanti?",6,"Partendo dalla caduta recente, raccontata come caso, e chiedendo ai partecipanti le loro esperienze: il bisogno di sapere nasce dal riconoscere il problema nel proprio lavoro.",["Ho usato un caso reale","Ho valorizzato l’esperienza"]),
  ("Scrivi la scaletta dei 60 minuti.",8,"10 minuti: caso e discussione. 10 minuti: errori tipici e regole essenziali, con immagini. 30 minuti: esercitazione pratica in area scale, controllo e posizionamento a coppie. 10 minuti: verifica pratica e impegni individuali.",["Ho dato più tempo alla pratica","Ho previsto una verifica"],None,120),
  ("Come verifichi l’apprendimento e il trasferimento sul lavoro?",6,"Prova pratica con lista di controllo; osservazioni del preposto nelle settimane successive; analisi delle segnalazioni sulle scale.",["Ho previsto una prova pratica","Ho previsto osservazioni sul lavoro"])],
 "Nel laboratorio progetti una lezione di sessanta minuti per manutentori esperti, secondo i principi dell’apprendimento degli adulti: apertura motivante, scaletta e verifica del trasferimento. Confronta ogni risposta con la soluzione di riferimento.","Accordo 17 aprile 2025 · art. 37 D.lgs. 81/2008")])
EA(K,'ZR38','Insegnare un’operazione: il metodo in quattro fasi',[LB("Laboratorio · Addestrare all’uso del transpallet elettrico","Prepari l’addestramento di un nuovo magazziniere all’uso del transpallet elettrico con il metodo in quattro fasi.",[
  ["Operazione","prelievo di un pallet da 600 kg dalla baia e deposito a terra in corsia"],["Rischi","schiacciamento dei piedi, urti, ribaltamento del carico, investimento"],["Tempo disponibile","45 minuti"]],[
  ("Descrivi le fasi Preparare e Presentare.",7,"Preparare: mettere a proprio agio il magazziniere, chiedere che cosa conosce, spiegare lo scopo e i rischi. Presentare: eseguire l’operazione passo per passo spiegando i punti chiave, come controllo iniziale, posizione dei piedi, velocità e stabilità del carico.",["Ho descritto Preparare","Ho descritto Presentare con i punti chiave"]),
  ("Descrivi le fasi Provare e Verificare.",7,"Provare: il magazziniere esegue l’operazione spiegando i punti chiave, l’istruttore corregge subito. Verificare: lavoro autonomo con controlli frequenti che si riducono nel tempo, e registrazione dell’addestramento con l’esito della prova.",["Ho descritto Provare","Ho descritto Verificare e la registrazione"]),
  ("Quali punti chiave inserisci nella lista di controllo?",6,"Controllo di freni, comandi e batteria; piedi lontani dalla macchina; forche completamente inserite e carico stabile; velocità ridotta in curva e negli incroci; deposito con forche a terra; parcheggio e spegnimento.",["Ho elencato controlli e comportamenti","Ho incluso il deposito sicuro"])],
 "Nel laboratorio prepari l’addestramento all’uso del transpallet elettrico con il metodo in quattro fasi: preparare, presentare, provare e verificare, con la lista di controllo. Confronta ogni risposta con la soluzione di riferimento.","Art. 2, lett. cc) e art. 37 D.lgs. 81/2008")])
EA(K,'ZR39','La breve riunione di sicurezza in reparto',[LB("Laboratorio · Preparare una breve riunione di sicurezza","Prepari una breve riunione di inizio turno dopo un quasi incidente con un carroponte.",[
  ["Evento","un carico è passato sopra un operatore durante una movimentazione con carroponte"],["Partecipanti","8 operatori del reparto"],["Tempo","10 minuti"]],[
  ("Scrivi il messaggio chiave e la scaletta.",6,"Messaggio: mai sostare o passare sotto i carichi sospesi. Scaletta: 2 minuti per il fatto; 3 minuti per le cause e la regola; 3 minuti per le domande e le proposte dei lavoratori; 2 minuti per l’impegno condiviso.",["Ho scritto un solo messaggio chiave","Ho rispettato i 10 minuti"]),
  ("Quali domande poni per coinvolgere i lavoratori?",5,"Dove capita più spesso di passare vicino ai carichi? Che cosa ci rende difficile rispettare la regola? Come ci accorgiamo che un carico sta per muoversi?",["Ho scritto domande aperte","Ho cercato le cause pratiche"]),
  ("Come registri e dai seguito alla riunione?",5,"Verbale breve con data, tema, partecipanti, proposte raccolte e azioni con responsabile; verifica delle azioni al successivo incontro.",["Ho previsto il verbale","Ho previsto il seguito delle azioni"])],
 "Nel laboratorio prepari una breve riunione di sicurezza di dieci minuti dopo un quasi incidente con un carroponte: messaggio, scaletta, domande e registrazione. Confronta ogni risposta con la soluzione di riferimento.","Art. 36 D.lgs. 81/2008 · UNI EN ISO 45001, punto 5.4")])
EA(K,'ZR40','L’addestramento e il suo tracciamento',[SC("L’addestramento senza tracce","Un’impresa dichiara di aver addestrato tutti i carrellisti, ma non ha alcuna registrazione.",[
 ("Che cosa serve per dimostrare l’addestramento?",[["Registrazione con contenuti, istruttore, durata e esito della prova pratica",True,"Corretto: l’addestramento va tracciato."],["Una dichiarazione del datore di lavoro",False,"Non basta."],["Il libretto della macchina",False,"Non dimostra l’addestramento."]]),
 ("Chi può svolgere l’addestramento?",[["Una persona esperta, sul luogo di lavoro",True,"Corretto: art. 37, comma 5."],["Chiunque",False,"Serve esperienza."],["Solo un ente esterno",False,"Non è obbligatorio."]]),
 ("I carrellisti hanno anche bisogno dell’abilitazione?",[["Sì: per i carrelli elevatori serve la specifica abilitazione prevista dall’Accordo, oltre all’addestramento sulla macchina specifica",True,"Corretto."],["No",False,"È prevista l’abilitazione."],["Basta la patente di guida",False,"Non sostituisce l’abilitazione."]])],
 "L’addestramento si svolge con persone esperte, si traccia con contenuti ed esiti e si somma all’abilitazione richiesta per le attrezzature specifiche.","Un addestramento senza registrazioni. Metti in ordine le evidenze.","Art. 37, c. 5, e art. 73 D.lgs. 81/2008 · Accordo 17 aprile 2025")])
